// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;

    function setUp() public { c = new Owned(); }

    function testFuzz_property(address attackerAddr, address originOwner) public {
        vm.assume(attackerAddr != address(0));
        vm.assume(originOwner != address(0));

        vm.deal(originOwner, 1 ether);

        bool ok;
        try c.setOwner(originOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
        assertTrue(c.owner() == originOwner);

        Forwarder f = new Forwarder(c);

        vm.startPrank(originOwner);
        try f.execSetOwner(attackerAddr) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        assertTrue(c.owner() == originOwner);
    }
}

contract Forwarder {
    Owned immutable c;
    constructor(Owned _c) { c = _c; }
    function execSetOwner(address _new) external {
        c.setOwner(_new);
    }
}
